import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u15")
C = "B1"
# Lições de aprofundamento (10–24): situações do dia a dia e gestão da conversa.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)
def N(id, nl, pt, art, pl=None): return V(id, nl, pt, "noun", art, pl)

L(10, "Na oficina de bicicletas", "Mijn band is lek.",
  ["Explicar uma avaria da bicicleta e pedir a reparação"],
  vocab=[N("v-ketting","ketting","corrente","de","kettingen")],
  ex=[("Kunt u mijn band plakken?","Pode remendar-me o pneu?"),("Mijn ketting loopt steeds van het tandwiel.","A corrente está sempre a saltar."),("Mijn remmen piepen.","Os meus travões chiam."),("Wanneer is de fiets klaar?","Quando está a bicicleta pronta?")],
  review=["v-band-plakken","v-fietsenmaker","v-lekke-band","v-rem"],
  cefr=C, exs=[
    MA([("fietsenmaker","oficina de bicicletas"),("ketting","corrente"),("een band plakken","remendar um pneu"),("lekke band","pneu furado")], "Bicicleta.", ["v-fietsenmaker","v-ketting","v-band-plakken","v-lekke-band"]),
    AR("ketting", "corrente", "de", "De ketting.", ["v-ketting"]),
    TR("pt-nl","Pode remendar-me o pneu?", ["Kunt u mijn band plakken","Kunt u mijn band plakken?","Kun je mijn band plakken"], "band plakken.", ["v-band-plakken"]),
    TR("pt-nl","Os meus travões chiam.", ["Mijn remmen piepen"], "remmen = travões.", ["v-rem"]),
    DL([("Fietsenmaker","Goedemiddag, wat kan ik voor u doen?","Boa tarde, em que posso ajudar?"),("Jij","","")], ["*Mijn achterband is lek en de ketting loopt steeds van het tandwiel.","Ik wil een fiets.|Não explica avaria.","Ketting plakken.|Errado."], "Explicar a avaria.", ["v-ketting","v-lekke-band"]),
    FB("Kunt u ook even naar de ___ kijken? Ze piepen.", ["remmen"], "Travões.", ["v-rem"], choices=["remmen","ketting","band"], tr="Pode também ver os travões? Chiam."),
    MC("O mecânico diz «Hij is morgen om vier uur klaar». «Hij» é…", ["*a bicicleta (de fiets)","o mecânico|Não.","o pneu|Possível, mas aqui é a bicicleta."], "de-palavras → hij.", ["v-fietsenmaker"]),
    FE(["Kunt","u","mijn","band","plakt?"], 4, "plakken", "Depois de kunt: infinitivo.", ["v-band-plakken"]),
    LI("Voor een band plakken rekenen we vijftien euro.", ["Voor een band plakken rekenen we vijftien euro","Voor een band plakken rekenen we 15 euro"], "Para remendar um pneu cobramos quinze euros.", "Preço.", ["v-band-plakken"]),
  ], diff=3, mins=5)

L(11, "Avaria nos comboios", "Er rijden geen treinen tussen Utrecht en Amersfoort.",
  ["Perceber avisos de perturbação e alternativas"],
  vocab=[N("v-busvervoer","vervangend busvervoer","autocarros de substituição","het"), X("v-omrijden","omrijden","dar a volta|fazer um desvio","verb"),
         N("v-reisinformatie","reisinformatie","informação de viagem","de")],
  ex=[("Door een storing rijden er geen treinen tussen Utrecht en Amersfoort.","Devido a uma avaria não há comboios entre Utrecht e Amersfoort."),("Er is vervangend busvervoer.","Há autocarros de substituição."),("U kunt omrijden via Amersfoort.","Pode fazer o desvio por Amersfoort."),("Kijk in de app voor actuele reisinformatie.","Veja na app a informação de viagem atualizada.")],
  review=["v-storing","v-vertraging","v-overstappen"],
  cefr=C, exs=[
    MA([("vervangend busvervoer","autocarros de substituição"),("omrijden","fazer um desvio"),("reisinformatie","informação de viagem"),("storing","avaria")], "Perturbações.", ["v-busvervoer","v-omrijden","v-reisinformatie","v-storing"]),
    CO("text","Omroepbericht","Beste reizigers, door een seinstoring rijden er tot ongeveer vijf uur geen treinen tussen Utrecht Centraal en Amersfoort. Er is vervangend busvervoer vanaf de busplatforms aan de Jaarbeurszijde. Reizigers naar Zwolle kunnen ook omrijden via Amsterdam. Houd de reisinformatie in de app in de gaten.",
       [("Até quando não há comboios?", ["*Até cerca das cinco","Até amanhã","Até às duas"]),("Onde estão os autocarros?", ["*No lado da Jaarbeurs","No centro da cidade","Em Amersfoort"]),("Como podem ir para Zwolle?", ["*Pelo desvio via Amesterdão","A pé","Não podem"])],
       "Aviso na estação (texto fictício).", ["v-busvervoer","v-omrijden"]),
    TR("pt-nl","Há autocarros de substituição.", ["Er is vervangend busvervoer","Er rijden vervangende bussen"], "busvervoer.", ["v-busvervoer"]),
    TR("pt-nl","Temos de fazer um desvio.", ["We moeten omrijden","Wij moeten omrijden","We moeten een omweg maken"], "omrijden.", ["v-omrijden"]),
    FB("___ een storing rijden er geen treinen.", ["Door"], "Causa: door.", ["v-storing"], choices=["Door","Met","Om"], tr="Devido a uma avaria não há comboios."),
    FE(["Er","rijdt","geen","treinen","tussen","Utrecht","en","Amersfoort."], 1, "rijden", "Plural: rijden.", ["v-storing"]),
    DL([("Reiziger","Pardon, rijdt deze trein naar Amersfoort?","Desculpe, este comboio vai para Amersfoort?"),("Medewerker NS","","")], ["*Nee, door een storing niet. Neemt u de vervangende bus, buiten links.","Ja hoor, altijd.|Ignora a avaria.","Omrijden is lekker.|Sem sentido."], "Informar.", ["v-busvervoer"]),
    LI("Houd de reisinformatie goed in de gaten.", ["Houd de reisinformatie goed in de gaten"], "Esteja atento à informação de viagem.", "Aviso.", ["v-reisinformatie"]),
    WO("Há autocarros de substituição.", ["Er","is","vervangend","busvervoer"], "Ordem.", ["v-busvervoer"]),
  ], diff=4, mins=6)

