    DL([("Jij","Mijn pasta is helaas koud.","A minha massa infelizmente está fria."),("Ober","","")], ["*Wat vervelend! Ik stuur hem meteen terug naar de keuken.","Eet smakelijk!|Ignora.","Dat zal wel.|Rude."], "Resposta do empregado.", ["v-terugsturen"]),
